#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

enum { MAX_RECORDS = 64, MAX_LINE = 24 };
enum LineStatus { LINE_OK, LINE_END, LINE_INVALID, LINE_IO_ERROR };
enum SummaryStatus { SUMMARY_OK, SUMMARY_INVALID, SUMMARY_IO_ERROR };

struct Summary {
    size_t count;
    long total;
};

static enum LineStatus read_line(FILE *stream, char line[MAX_LINE + 1])
{
    size_t length = 0;
    for (;;) {
        int ch = fgetc(stream);
        if (ch == EOF) {
            if (ferror(stream)) {
                return LINE_IO_ERROR;
            }
            return length == 0 ? LINE_END : LINE_INVALID;
        }
        if (ch == '\n') {
            line[length] = '\0';
            return LINE_OK;
        }
        if (ch == '\0' || ch > 127 || length == MAX_LINE) {
            return LINE_INVALID;
        }
        line[length++] = (char)ch;
    }
}

static int read_number(const char *text, char **end, int maximum)
{
    if (*text < '0' || *text > '9') {
        return -1;
    }
    errno = 0;
    long value = strtol(text, end, 10);
    if (errno == ERANGE || value > maximum) {
        return -1;
    }
    return (int)value;
}

static int read_record(const char *line, int *id, int *value)
{
    char *end;
    *id = read_number(line, &end, 9999);
    if (*id < 1 || *end != '\t') {
        return 0;
    }
    *value = read_number(end + 1, &end, 999);
    if (*value < 0) {
        return 0;
    }
    return *end == '\0';
}

static enum SummaryStatus summarize(FILE *stream, struct Summary *summary)
{
    int ids[MAX_RECORDS];
    char line[MAX_LINE + 1];
    for (;;) {
        enum LineStatus status = read_line(stream, line);
        if (status == LINE_END) {
            return SUMMARY_OK;
        }
        if (status == LINE_IO_ERROR) {
            return SUMMARY_IO_ERROR;
        }
        int id;
        int value;
        if (status == LINE_INVALID || summary->count == MAX_RECORDS ||
            !read_record(line, &id, &value)) {
            return SUMMARY_INVALID;
        }
        for (size_t i = 0; i < summary->count; ++i) {
            if (ids[i] == id) {
                return SUMMARY_INVALID;
            }
        }
        ids[summary->count++] = id;
        summary->total += value;
    }
}

int main(void)
{
    FILE *input = fopen("reading.tsv", "rb");
    if (input == NULL) {
        puts("open-input-error");
        return 1;
    }

    struct Summary summary = {0, 0};
    enum SummaryStatus status = summarize(input, &summary);
    int close_status = fclose(input);
    if (status == SUMMARY_INVALID) {
        printf("invalid line %zu\n", summary.count + 1);
        return 1;
    }
    if (status == SUMMARY_IO_ERROR) {
        puts("read-error");
        return 1;
    }
    if (close_status == EOF) {
        puts("close-input-error");
        return 1;
    }


    FILE *report = fopen("totals.tsv", "wb");
    if (report == NULL) {
        puts("open-output-error");
        return 1;
    }
    int failed = fprintf(report, "records\ttotal\n%zu\t%ld\n", summary.count, summary.total) < 0;
    int report_close = fclose(report);
    if (failed || report_close == EOF) {
        puts(failed ? "write-error" : "close-output-error");
        return 1;
    }
    puts("ok");
    return 0;
}

